package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class CourseMyFeedbackIntegrationTest {
 SubmissionFeedbackStoreIntegrationTest f;CourseMyFeedbackStore store;CourseStore courses;UUID course;FeedbackRetractionStore markers;
 @BeforeEach void setup(){f=new SubmissionFeedbackStoreIntegrationTest();f.setup();courses=new CourseStore(f.f.f.source,Clock.systemUTC());var c=courses.create(f.f.group,f.f.space,f.f.f.owner,f.f.f.key(),"Feedback Course","Shared",f.f.f.trace).course();course=c.courseId();courses.curriculum(f.f.group,f.f.space,course,f.f.f.owner,1,List.of(f.f.study),f.f.f.trace);store=new CourseMyFeedbackStore(f.f.f.source,courses);markers=new FeedbackRetractionStore(f.f.f.source,f.f.parent.store,f.f.store,Clock.systemUTC());}
 CourseMyFeedbackStore.Page list(String filter,UUID after,int limit){return store.list(f.f.group,f.f.space,course,f.f.author,after,limit,filter);}
 CourseMyFeedbackStore.Row row(){return list("ALL",null,100).items().stream().filter(v->v.submissionId().equals(f.answer.submissionId())).findFirst().orElseThrow();}
 FeedbackRetractionStore.Retraction mark(long target,long expected,String state){return markers.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,target,expected,new FeedbackRetractionInput(state,"PRIVATE marker reason"),f.f.f.trace);}
 UUID task(){var id=f.f.parent.create(f.f.f.key()).assignment().assignmentId();f.f.parent.store.state(f.f.group,f.f.space,f.f.study,id,f.f.f.owner,1,"OPEN",f.f.f.trace);return id;}
 @Test void absenceReadAndOwnScopeDoNotExposePeersOrCreateFeedback(){
  int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:CourseMyFeedbackStore.FILTERS)assertTrue(list(filter,null,20).items().isEmpty());assertNull(f.get(f.f.author,false).feedback());assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));f.change(0,1,"MY PRIVATE FEEDBACK");
  UUID peer=f.f.f.ids.next();for(UUID actor:List.of(peer,f.f.f.owner)){var sub=f.f.store.submit(f.f.group,f.f.space,f.f.study,f.f.assignment,actor,0,2,f.f.f.key(),"PRIVATE OTHER ANSWER",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,f.f.study,f.f.assignment,sub.submissionId(),f.f.f.owner,0,new SubmissionFeedbackInput("PRIVATE OTHER FEEDBACK",1,2),f.f.f.trace);assertEquals(sub.submissionId(),store.list(f.f.group,f.f.space,course,actor,null,20,"ALL").items().getFirst().submissionId());}
  UUID absent=task();f.f.store.submit(f.f.group,f.f.space,f.f.study,absent,f.f.author,0,2,f.f.f.key(),"NO COMMENT",f.f.f.trace);assertEquals(1,list("ALL",null,20).items().size());var json=tools.jackson.databind.json.JsonMapper.builder().build().valueToTree(row());assertEquals(15,json.size());for(String key:List.of("authorId","content","reason","score","reviewerId","snapshot","feedbackId"))assertFalse(json.has(key));assertEquals("CURRENT",row().feedbackStatus());assertTrue(store.list(f.f.group,f.f.space,course,f.f.f.ids.next(),null,20,"ALL").items().isEmpty());
 }
 @Test void resubmissionKeepsPriorOpinionAndRetractedFilterIncludesOldAnswer(){
  f.change(0,1,"Original feedback");assertEquals("CURRENT",row().feedbackStatus());f.f.submit(f.f.f.key(),1,2,"New answer");assertEquals("OUTDATED",row().feedbackStatus());assertEquals(1L,row().feedbackSubmissionVersion());mark(1,0,"RETRACTED");assertEquals("OUTDATED",row().feedbackStatus());assertEquals("RETRACTED",row().feedbackRetractionState());assertEquals(1,list("OUTDATED",null,20).items().size());assertEquals(1,list("RETRACTED",null,20).items().size());assertTrue(list("CURRENT",null,20).items().isEmpty());f.change(1,2,"Original feedback");assertEquals("CURRENT",row().feedbackStatus());assertEquals(2L,row().feedbackVersion());assertEquals(2L,row().feedbackSubmissionVersion());assertEquals("NONE",row().feedbackRetractionState());assertTrue(list("RETRACTED",null,20).items().isEmpty());
 }
 @Test void latestFeedbackVersionAloneDeterminesCurrentMarkerAndRestoration(){
  f.change(0,1,"First");mark(1,0,"RETRACTED");assertEquals("RETRACTED",row().feedbackStatus());mark(1,1,"RESTORED");assertEquals("CURRENT",row().feedbackStatus());assertEquals("RESTORED",row().feedbackRetractionState());f.change(1,1,"New text");mark(1,2,"RETRACTED");assertEquals("CURRENT",row().feedbackStatus());assertEquals("NONE",row().feedbackRetractionState());assertNull(row().retractionVersion());mark(2,0,"RETRACTED");assertEquals("RETRACTED",row().feedbackStatus());assertEquals(1,list("RETRACTED",null,20).items().size());mark(2,1,"RESTORED");assertEquals("CURRENT",row().feedbackStatus());assertEquals(2L,row().retractionVersion());
 }
 @Test void unknownMarkerFailsClosedInsteadOfEndorsingCurrentOpinion(){
  f.change(0,1,"PRIVATE feedback");var marker=mark(1,0,"RETRACTED");String saved=f.f.f.jdbc.queryForObject("SELECT snapshot::text FROM feedback_retraction WHERE retraction_id=?",String.class,marker.retractionId());try{for(String expression:List.of("snapshot-'state'","jsonb_set(snapshot,'{state}','\"INVALID\"')")){f.f.f.jdbc.update("UPDATE feedback_retraction SET snapshot="+expression+" WHERE retraction_id=?",marker.retractionId());assertEquals("UNAVAILABLE",row().feedbackStatus());assertEquals("UNKNOWN",row().feedbackRetractionState());assertTrue(list("CURRENT",null,20).items().isEmpty());assertTrue(list("RETRACTED",null,20).items().isEmpty());assertEquals(1,list("UNAVAILABLE",null,20).items().size());}}finally{f.f.f.jdbc.update("UPDATE feedback_retraction SET snapshot=?::jsonb WHERE retraction_id=?",saved,marker.retractionId());}
 }
 @Test void keysetFiltersBeforeLimitAcrossOwnAssignments(){
  f.change(0,1,"First");for(int n=0;n<10;n++){UUID assignment=task();var sub=f.f.store.submit(f.f.group,f.f.space,f.f.study,assignment,f.f.author,0,2,f.f.f.key(),"ANSWER",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,f.f.study,assignment,sub.submissionId(),f.f.f.owner,0,new SubmissionFeedbackInput("COMMENT",1,2),f.f.f.trace);if(n%2==0)f.f.store.submit(f.f.group,f.f.space,f.f.study,assignment,f.f.author,1,2,f.f.f.key(),"NEW ANSWER",f.f.f.trace);}
  assertEquals(11,list("ALL",null,100).items().size());assertEquals(6,list("CURRENT",null,100).items().size());assertEquals(5,list("OUTDATED",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("CURRENT",after,2);seen.addAll(p.items().stream().map(CourseMyFeedbackStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("CURRENT",null,100).items().stream().map(CourseMyFeedbackStore.Row::submissionId).toList(),seen);assertEquals(6,new HashSet<>(seen).size());
 }
 @Test void currentSharedLabelsPreserveOriginalInstructionsAndExactScope(){
  f.change(0,1,"Original");f.f.parent.store.metadata(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"New <script> title","New instructions",f.f.f.trace);assertEquals("New <script> title",row().assignmentTitle());assertEquals(2,row().assignmentVersion());assertEquals(2,f.get(f.f.author,false).feedback().assignmentVersion());f.status(404,()->store.list(f.f.f.ids.next(),f.f.space,course,f.f.author,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.f.ids.next(),course,f.f.author,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.space,f.f.f.ids.next(),f.f.author,null,20,"ALL"));UUID empty=courses.create(f.f.group,f.f.space,f.f.f.owner,f.f.f.key(),"Empty Course","Shared",f.f.f.trace).course().courseId();assertTrue(store.list(f.f.group,f.f.space,empty,f.f.author,null,20,"ALL").items().isEmpty());for(int limit:List.of(0,101))f.status(400,()->list("ALL",null,limit));for(String filter:List.of("current","MISSING","REQUESTED","","CURRENT' OR TRUE--"))f.status(400,()->list(filter,null,20));
 }
 @Test void closedArchivedReadsKeepOriginalOpinionMarkerAndEventsUnchanged(){
  var feedback=f.change(0,1,"Original");var marker=mark(1,0,"RETRACTED");f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"CLOSED",f.f.f.trace);f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,3,"RETIRED",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.f.owner,1,"RETIRED",f.f.f.trace);int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:CourseMyFeedbackStore.FILTERS)list(filter,null,20);assertEquals("RETRACTED",row().feedbackStatus());assertEquals(feedback,f.get(f.f.author,false).feedback());assertEquals(marker,markers.get(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.author,false,1).retraction());assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
 }
 @Test void concurrentAnswerAndFeedbackReadsShareOneStatementSnapshot()throws Exception{
  f.change(0,1,"Original");try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var reader=pool.submit(()->{barrier.await();for(int n=0;n<30;n++){var v=row();assertTrue(v.feedbackSubmissionVersion()<=v.version());if(v.feedbackStatus().equals("CURRENT"))assertEquals(v.version(),v.feedbackSubmissionVersion());else assertEquals("OUTDATED",v.feedbackStatus());}return true;});var writer=pool.submit(()->{barrier.await();f.f.submit(f.f.f.key(),1,2,"New answer");return f.change(1,2,"New feedback");});assertTrue(reader.get(20,TimeUnit.SECONDS));assertEquals(2,writer.get(20,TimeUnit.SECONDS).version());assertEquals("CURRENT",row().feedbackStatus());}
 }

 UUID task(UUID study){var id=f.f.parent.store.create(f.f.group,f.f.space,study,f.f.f.owner,f.f.f.key(),"Course task <script>","Shared",f.f.f.trace).assignment().assignmentId();f.f.parent.store.state(f.f.group,f.f.space,study,id,f.f.f.owner,1,"OPEN",f.f.f.trace);return id;}
 SubmissionStore.Submission commented(UUID study,UUID assignment,boolean outdated){var answer=f.f.store.submit(f.f.group,f.f.space,study,assignment,f.f.author,0,2,f.f.f.key(),"PRIVATE ANSWER",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,study,assignment,answer.submissionId(),f.f.f.owner,0,new SubmissionFeedbackInput("PRIVATE COMMENT",1,2),f.f.f.trace);if(outdated)f.f.store.submit(f.f.group,f.f.space,study,assignment,f.f.author,1,2,f.f.f.key(),"NEW PRIVATE ANSWER",f.f.f.trace);return answer;}
 @Test void currentCurriculumAndSharedLabelsPreservePinnedSourceAndArchivedReadsNeverEnroll(){
  f.change(0,1,"MY COMMENT");var b=f.f.parent.parent.create(f.f.f.key()).study();var outside=f.f.parent.parent.create(f.f.f.key()).study();UUID bTask=task(b.studyId()),outsideTask=task(outside.studyId());commented(b.studyId(),bTask,false);commented(outside.studyId(),outsideTask,false);assertEquals(1,list("ALL",null,100).items().size());var c=courses.curriculum(f.f.group,f.f.space,course,f.f.f.owner,2,List.of(f.f.study,b.studyId()),f.f.f.trace);assertEquals(2,list("ALL",null,100).items().size());assertTrue(list("ALL",null,100).items().stream().noneMatch(v->v.studyId().equals(outside.studyId())));
  f.f.parent.parent.store.metadata(f.f.group,f.f.space,b.studyId(),f.f.f.owner,1,"Current B <script>","Current description",f.f.f.trace);assertEquals("Current B <script>",list("ALL",null,100).items().stream().filter(v->v.studyId().equals(b.studyId())).findFirst().orElseThrow().studyTitle());assertEquals(b.title(),courses.get(f.f.group,f.f.space,course).studies().get(1).title());
  c=courses.curriculum(f.f.group,f.f.space,course,f.f.f.owner,c.version(),List.of(b.studyId()),f.f.f.trace);assertEquals(bTask,list("ALL",null,100).items().getFirst().assignmentId());assertEquals(1,list("ALL",null,100).items().size());c=courses.state(f.f.group,f.f.space,course,f.f.f.owner,c.version(),"RETIRED",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,b.studyId(),f.f.f.owner,2,"RETIRED",f.f.f.trace);int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:CourseMyFeedbackStore.FILTERS)list(filter,null,20);assertEquals("RETIRED",list("ALL",null,20).items().getFirst().courseState());assertEquals("CURRENT",list("ALL",null,20).items().getFirst().feedbackStatus());assertEquals(0,f.f.f.jdbc.queryForObject("SELECT count(*) FROM course_enrollment WHERE course_id=?",Integer.class,course));assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
 }
 @Test void filterKeysetSpansCanonicalStudiesWithIndependentLatestFeedbackAnnotations(){
  f.change(0,1,"FIRST");var b=f.f.parent.parent.create(f.f.f.key()).study();var outside=f.f.parent.parent.create(f.f.f.key()).study();courses.curriculum(f.f.group,f.f.space,course,f.f.f.owner,2,List.of(f.f.study,b.studyId()),f.f.f.trace);for(int n=0;n<12;n++){UUID study=n%2==0?f.f.study:b.studyId();UUID assignment=task(study);var answer=commented(study,assignment,n%3==0);if(n%3==0)markers.change(f.f.group,f.f.space,study,assignment,answer.submissionId(),f.f.f.owner,1,0,new FeedbackRetractionInput("RETRACTED","PRIVATE REASON"),f.f.f.trace);}commented(outside.studyId(),task(outside.studyId()),false);assertEquals(13,list("ALL",null,100).items().size());assertEquals(9,list("CURRENT",null,100).items().size());assertEquals(4,list("OUTDATED",null,100).items().size());assertEquals(4,list("RETRACTED",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("CURRENT",after,2);seen.addAll(p.items().stream().map(CourseMyFeedbackStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("CURRENT",null,100).items().stream().map(CourseMyFeedbackStore.Row::submissionId).toList(),seen);assertEquals(9,new HashSet<>(seen).size());for(var row:list("RETRACTED",null,100).items())assertEquals("OUTDATED",row.feedbackStatus());
 }
}
